import { useState } from 'react';

// Boundary: ChipBar manages its own pressed state visually only.
// Grid filtering is wired externally — a parent will pass an onFilterChange
// callback when that integration is built.

export type ChipBarProps = {
  labels: string[];
};

export function ChipBar({ labels }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<string | null>(null);

  function handleClick(label: string): void {
    setPressed(prev => (prev === label ? null : label));
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter chips">
      {labels.map(label => (
        <button
          key={label}
          className={`chip${pressed === label ? ' chip--pressed' : ''}`}
          aria-pressed={pressed === label}
          onClick={() => handleClick(label)}
          type="button"
        >
          {label}
        </button>
      ))}
    </div>
  );
}
